"""Generate and check the committed SQL/Protobuf contracts from schema.py."""
import argparse
from pathlib import Path
from schema import TABLES, PROTO_TYPES, CH_TYPES

ROOT = Path(__file__).resolve().parent.parent


def generate():
    proto = ['syntax = "proto3";', 'package capibara.v1;',
             '// Generated by pipeline/generate_schema.py. Never reuse field numbers.']
    sql = ['-- Generated by pipeline/generate_schema.py.',
           'CREATE DATABASE IF NOT EXISTS raw;', 'CREATE DATABASE IF NOT EXISTS stream;']
    for name, message, _, keys, fields in TABLES:
        proto.append(f'\nmessage {message} {{')
        for number, (_, wire, kind) in enumerate(fields, 1):
            proto.append(f'  {PROTO_TYPES[kind]} {wire} = {number};')
        proto.extend(['  uint64 source_version = 100;', '  string source_file = 101;', '}'])
        columns = [f'  {wire} {CH_TYPES[kind]}' for _, wire, kind in fields]
        columns += ['  source_version UInt64', '  source_file String']
        definition = ',\n'.join(columns)
        key = ', '.join(keys)
        consumers = 2 if name in ('orders', 'order_items') else 1
        sql.append(f'''\nCREATE TABLE IF NOT EXISTS raw.{name} (\n{definition}\n)
ENGINE = ReplacingMergeTree(source_version) ORDER BY ({key});
CREATE TABLE IF NOT EXISTS stream.{name} (\n{definition}\n)
ENGINE = Kafka SETTINGS
 kafka_broker_list = 'kafka:9092', kafka_topic_list = 'capibara.v1.{name}',
 kafka_group_name = 'capibara-clickhouse-v1-{name}',
 kafka_format = 'ProtobufSingle', kafka_schema = 'marketplace.proto:{message}',
 kafka_num_consumers = {consumers}, kafka_thread_per_consumer = 1,
 kafka_max_block_size = 16384, kafka_flush_interval_ms = 1000,
 kafka_skip_broken_messages = 0;
CREATE MATERIALIZED VIEW IF NOT EXISTS stream.{name}_sink TO raw.{name}
AS SELECT * FROM stream.{name};''')
    return {'schemas/marketplace.proto': '\n'.join(proto) + '\n',
            'clickhouse/01_ingestion.sql': '\n'.join(sql) + '\n'}


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    for filename, content in generate().items():
        target = ROOT / filename
        if args.check:
            if not target.exists() or target.read_text() != content:
                raise SystemExit(f'Generated contract is stale: {filename}')
        else:
            target.write_text(content)
